local({
  items <- cbind(coalesce(as.numeric(q012), as.numeric(b012)), coalesce(as.numeric(q021), as.numeric(b021)))
  items[!items %in% 1:3] <- NA
  case_when(
    rowSums(items == 1 | items == 3, na.rm = TRUE) > 0 ~ "TRUE",
    rowSums(items == 2, na.rm = TRUE) > 0 ~ "FALSE",
    .default = NA_character_
  )
})

local({
  grade <- as.numeric(GRADE)
  case_when(!grade %in% 3:5 ~ NA_character_, wave == "4" ~ paste("Grade", grade + 1), .default = paste("Grade", grade))
})

local({
  hours <- sapply(list(list(q023.1, q023.2, q023.3, b023.1, b023.2, b023.3)), function(d) {
    wave2 <- sapply(d[4:6], function(b) {
      x <- as.numeric(b)
      case_when(
        x >= 0 & x <= 69 ~ x / 10,
        x >= 70 & x <= 77 ~ c(6.5, 7, 7.5, 8, 9, 10, 11, 12)[match(x, 70:77)],
        x == 80 ~ 0.125,
        .default = NA_real_
      )
    })
    blank <- sapply(d[4:6], function(b) as.numeric(b) %in% 96)
    wave2[blank & rowSums(!is.na(wave2)) > 0] <- 0
    coalesce((d[[1]] + d[[2]] + d[[3]]) / 10, wave2[, 1] + wave2[, 2] + wave2[, 3])
  })
  hours[, 1]
})

