local({
  wd <- coalesce(
    ((as.numeric(q037) - as.numeric(q036)) / 3600) %% 24,
    ((as.numeric(b037) - as.numeric(b036)) / 3600) %% 24
  )
  we <- coalesce(
    ((as.numeric(q039) - as.numeric(q038)) / 3600) %% 24,
    ((as.numeric(b039) - as.numeric(b038)) / 3600) %% 24
  )
  (5 * wd + 2 * we) / 7
})
